// Bundles each API entry in server/entries/ into one self-contained file in api/ (what Vercel runs).
//   npm run build:api        (also runs as part of `npm run build`)
// The generated files are committed; tests/api-bundle.test.ts fails if they fall out of date.
import { build } from "esbuild";
import { readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { resolve } from "node:path";

const root = resolve(fileURLToPath(import.meta.url), "../..");
const BANNER = "// GENERATED by scripts/build-api.mjs from server/entries/ and everything it imports. Do not edit; run `npm run build:api`.";

export async function bundleApi({ write = true } = {}) {
  const names = readdirSync(resolve(root, "server/entries")).filter((f) => f.endsWith(".ts")).map((f) => f.replace(/\.ts$/, ""));
  const result = await build({
    entryPoints: Object.fromEntries(names.map((n) => [n, resolve(root, `server/entries/${n}.ts`)])),
    outdir: resolve(root, "api"),
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node20",
    outExtension: { ".js": ".js" },
    banner: { js: BANNER },
    legalComments: "none",
    write,
    logLevel: "warning",
  });
  return result.outputFiles ?? [];
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  await bundleApi();
  console.log("api/ bundled");
}
